import { ConflictError } from "./domain-error";
import { TaskStatus } from "./task-status";

export interface TaskProps {
  id: string;
  projectId: string;
  title: string;
  description: string;
  dueDate?: Date;
  status: TaskStatus;
  assigneeId?: string;
}

export class Task {
  constructor(private props: TaskProps) {}

  get id(): string { return this.props.id; }
  get projectId(): string { return this.props.projectId; }
  get title(): string { return this.props.title; }
  get description(): string { return this.props.description; }
  get dueDate(): Date | undefined { return this.props.dueDate; }
  get status(): TaskStatus { return this.props.status; }
  get assigneeId(): string | undefined { return this.props.assigneeId; }

  assignTo(userId: string): void {
    this.props.assigneeId = userId;
  }

  markDone(): void {
    if (this.props.status === "done") {
      throw new ConflictError("task is already done");
    }
    this.props.status = "done";
  }
}

